gn: left; transition: all .2s; }.suggestions button:hover, .quick-bar button:hover { border-color: var(--brand); color: var(--brand); transform: translateY(-1px); }.message { display: flex; gap: 11px; margin-bottom: 24px; }.message.user { flex-direction: row-reverse; }.message-avatar { display: grid; place-items: center; flex: none; width: 30px; height: 30px; border-radius: 9px; color: #fff; background: var(--violet); font-size: 11px; font-weight: 700; }.message.user .message-avatar { background: var(--brand); }.message-content { max-width: 80%; }.message.user .message-content { text-align: right; }.message-meta { margin-bottom: 6px; color: var(--muted); font-size: 12px; }.message-meta small { margin-left: 6px; color: var(--faint); }.message-text { display: inline-block; padding: 12px 14px; border-radius: 4px 14px 14px 14px; color: var(--ink-2); background: #f3f5f9; font-size: 14px; line-height: 1.7; white-space: pre-wrap; text-align: left; }.message.user .message-text { border-radius: 14px 4px 14px 14px; color: #fff; background: var(--brand); }.citation { margin-top: 8px; color: var(--muted); font-size: 11px; text-align: left; }.typing { display: flex; gap: 4px; padding: 14px; border-radius: 4px 14px 14px 14px; background: #f3f5f9; }.typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--faint); animation: blink 1s infinite; }.typing i:nth-child(2) { animation-delay: .15s; }.typing i:nth-child(3) { animation-delay: .3s; }@keyframes blink { 0%, 80%, 100% { opacity: .3; } 40% { opacity: 1; } }.quick-bar { display: flex; align-items: center; gap: 8px; padding: 10px 20px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; overflow: auto; }.quick-bar button { flex: none; padding: 6px 10px; font-size: 12px; }.composer { display: flex; align-items: flex-end; gap: 10px; padding: 14px 20px 8px; border-top: 1px solid var(--line); }.composer :deep(.el-textarea__inner) { box-shadow: none; border: 0; background: #f7f8fa; }.composer .el-button { height: 42px; }.composer-tip { padding: 0 20px 14px; color: var(--faint); font-size: 11px; }.context-card { padding: 20px; }.context-title { display: flex; align-items: center; justify-content: space-between; font-weight: 600; }.live { display: flex; align-items: center; gap: 6px; color: var(--ok); font-size: 10px; letter-spacing: .08em; }.context-kpis { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 20px 0; }.context-kpis div { padding: 12px; border-radius: 10px; background: var(--bg); }.context-kpis strong, .context-kpis span { display: block; }.context-kpis strong { font-size: 22px; }.context-kpis span { margin-top: 3px; color: var(--muted); font-size: 11px; }.context-kpis .green { color: var(--ok); }.context-kpis .orange { color: var(--warn); }.context-kpis .violet { color: var(--violet); }.context-section { padding-top: 18px; border-top: 1px solid var(--line); }.section-label { margin-bottom: 10px; font-weight: 600; font-size: 13px; }.context-alert { display: flex; gap: 9px; padding: 9px 0; }.context-alert > span { flex: none; width: 7px; height: 7px; margin-top: 5px; border-radius: 50%; background: var(--danger-vivid); }.context-alert strong, .context-alert small { display: block; }.context-alert strong { font-size: 12px; }.context-alert small { margin-top: 3px; color: var(--muted); font-size: 11px; }.context-section ul { padding-left: 17px; margin: 0; color: var(--muted); font-size: 12px; line-height: 2; }
@media (max-width: 900px) { .chat-head { align-items: flex-start; flex-direction: column; gap: 12px; }.chat-layout { grid-template-columns: 1fr; }.context-card { min-height: auto; }.suggestions { grid-template-columns: 1fr; } }
